record.field:
# Buscar gateways de WhatsApp
gateways = env['mail.gateway'].search([('gateway_type', '=', 'whatsapp')])

if not gateways:
    raise UserError('No se encontraron gateways de WhatsApp configurados.')

# Obtener el modelo pos.order
pos_order_model = env.ref('point_of_sale.model_pos_order').id

# Plantilla normal
template_name = 'Ticket POS WhatsApp'
for gateway in gateways:
    existing = env['mail.whatsapp.template'].search([
        ('name', '=', template_name),
        ('gateway_id', '=', gateway.id),
    ], limit=1)
    if not existing:
        template = env['mail.whatsapp.template'].create({
            'name': template_name,
            'body': '🧾 *Ticket de Compra*\n\nHola {{1}},\n\nGracias por tu compra en {{2}}.\n\n📝 Pedido: {{3}}\n💰 Total: {{4}}\n📅 Fecha: {{5}}\n\n¡Gracias por tu preferencia!',
            'category': 'utility',
            'language': 'es',
            'model_id': pos_order_model,
            'gateway_id': gateway.id,
            'state': 'draft',
        })
        variables = [
            {'sequence': 1, 'variable_index': 1, 'name': 'Nombre del Cliente', 'field_name': 'partner_id.name', 'demo_value': 'Sample value'},
            {'sequence': 2, 'variable_index': 2, 'name': 'Nombre de la Tienda', 'field_name': 'config_id.name', 'demo_value': 'Sample value'},
            {'sequence': 3, 'variable_index': 3, 'name': 'Número de Pedido', 'field_name': 'name', 'demo_value': 'Sample value'},
            {'sequence': 4, 'variable_index': 4, 'name': 'Total', 'field_name': 'amount_total', 'demo_value': 'Sample value'},
            {'sequence': 5, 'variable_index': 5, 'name': 'Fecha', 'field_name': 'date_order', 'demo_value': 'Sample value'},
        ]
        for var in variables:
            var['template_id'] = template.id
            var['field_type'] = 'field'
            env['mail.whatsapp.template.variable'].create(var)

# Plantilla interactiva
interactive_name = 'Ticket POS WhatsApp Interactivo'
for gateway in gateways:
    existing = env['mail.whatsapp.template'].search([
        ('name', '=', interactive_name),
        ('gateway_id', '=', gateway.id),
    ], limit=1)
    if not existing:
        template = env['mail.whatsapp.template'].create({
            'name': interactive_name,
            'body': '¿Desea recibir su ticket de la compra realizada recientemente? Pulse el botón correspondiente.',
            'category': 'utility',
            'language': 'es',
            'model_id': pos_order_model,
            'gateway_id': gateway.id,
            'state': 'draft',
            'interactive': True,
            'buttons': [
                {
                    'type': 'reply',
                    'reply': {
                        'id': 'si_ticket',
                        'title': 'Sí',
                        'description': 'Recibir ticket de compra',
                    }
                },
                {
                    'type': 'reply',
                    'reply': {
                        'id': 'no_ticket',
                        'title': 'No',
                        'description': 'No recibir ticket',
                    }
                }
            ],
        })

action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Plantillas POS',
        'message': 'Plantillas de WhatsApp para POS creadas correctamente',
        'type': 'success',
        'sticky': False,
    }
}
